    .reg .u32 %r<64>;
    .reg .f32 %f<64>;
    .reg .pred %p<16>;

    .shared .align 4 .f32 sdata[1024];

    ld.param.u64 %rd1, [anchor_ptr];
    ld.param.u64 %rd2, [positive_ptr];
    ld.param.u64 %rd3, [negative_ptr];
    ld.param.u64 %rd4, [output_ptr];
    ld.param.f32 %f1, [margin];
    ld.param.u32 %r1, [batch_size];
    ld.param.u32 %r2, [dim];

    cvta.to.global.u64 %rd1, %rd1;
    cvta.to.global.u64 %rd2, %rd2;
    cvta.to.global.u64 %rd3, %rd3;
    cvta.to.global.u64 %rd4, %rd4;

    mov.f32 %f0, 0f358637BD;      // eps = 1e-6

    mov.u32 %r3, %tid.x;
    mov.u32 %r4, %ntid.x;

    mov.f32 %f2, 0f00000000;      // thread_sum
    mov.u32 %r5, %r3;             // row = tid

