    setp.ge.u32 %p1, %r5, %r1;
    @%p1 bra END_ROW_LOOP;

    mul.lo.u32  %r6, %r5, %r2;        // base elements
    cvt.u64.u32 %rd10, %r6;
    mul.lo.u64  %rd11, %rd10, 4;      // base bytes

    add.u64 %rd12, %rd1, %rd11;       // anchor row ptr
    add.u64 %rd13, %rd2, %rd11;       // positive row ptr
    add.u64 %rd14, %rd3, %rd11;       // negative row ptr

    mov.f32 %f3, 0f00000000;          // sum_pos
    mov.f32 %f4, 0f00000000;          // sum_neg
    mov.u32 %r7, 0;                   // k

LOOP_K:
    setp.ge.u32 %p2, %r7, %r2;
    @%p2 bra END_K_LOOP;

    cvt.u64.u32 %rd15, %r7;
    mul.lo.u64  %rd16, %rd15, 4;

    add.u64 %rd17, %rd12, %rd16;
    add.u64 %rd18, %rd13, %rd16;
    add.u64 %rd19, %rd14, %rd16;

    ld.global.f32 %f5, [%rd17];
    ld.global.f32 %f6, [%rd18];
    ld.global.f32 %f7, [%rd19];

    sub.f32 %f8, %f5, %f6;
    add.f32 %f8, %f8, %f0;
    fma.rn.f32 %f3, %f8, %f8, %f3;

    sub.f32 %f9, %f5, %f7;
    add.f32 %f9, %f9, %f0;
    fma.rn.f32 %f4, %f9, %f9, %f4;

    add.u32 %r7, %r7, 1;
    bra LOOP_K;

END_K_LOOP:
    sqrt.rn.f32 %f10, %f3;
    sqrt.rn.f32 %f11, %f4;

    sub.f32 %f12, %f10, %f11;
    add.f32 %f13, %f12, %f1;

    mov.f32 %f14, 0f00000000;
    max.f32 %f15, %f13, %f14;

    add.f32 %f2, %f2, %f15;

    add.u32 %r5, %r5, %r4;
    bra LOOP_ROW;

END_ROW_LOOP:
    mov.u32 %r8, %tid.x;
    mul.wide.u32 %rd20, %r8, 4;
    mov.u64 %rd21, sdata;
    add.u64 %rd22, %rd21, %rd20;
    st.shared.f32 [%rd22], %f2;

    bar.sync 0;

    mov.u32 %r9, %ntid.x;
    shr.u32 %r10, %r9, 1;

RED_LOOP:
    setp.eq.u32 %p3, %r10, 0;
    @%p3 bra RED_DONE;

    setp.lt.u32 %p4, %r8, %r10;
    @!%p4 bra RED_SKIP;

    add.u32 %r11, %r8, %r10;
    mul.wide.u32 %rd23, %r11, 4;
    add.u64 %rd24, %rd21, %rd23;
    ld.shared.f32 %f16, [%rd24];
    ld.shared.f32 %f17, [%rd22];
    add.f32 %f18, %f17, %f16;
    st.shared.f32 [%rd22], %f18;

RED_SKIP:
